/* Weather Pro isolated Dashboard base only. iOS Weather inspired, original implementation */
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Thai:wght@400;500;600;700&family=Inter:wght@400;500;600;700;800&display=swap');
.wp-group,.wp-group.nrdb-ui-group{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important}
.wp-group .nrdb-ui-widget{padding:0!important}
.wp-root{position:relative;overflow:hidden;isolation:isolate;max-width:1400px;margin:0 auto;color:#f6f9ff;min-height:84vh;border-radius:22px;padding:26px 22px 38px;background:radial-gradient(ellipse at 75% 0%,rgba(108,166,223,.37),transparent 48%),linear-gradient(160deg,#162e50 0%,#10243f 45%,#081525 100%);font-family:'Inter','IBM Plex Sans Thai',system-ui,sans-serif}
.wp-root:before{content:'';position:absolute;z-index:-1;inset:0;opacity:.32;pointer-events:none;background-image:radial-gradient(circle at 26% 12%,#a5c8ec 1px,transparent 2px),radial-gradient(circle at 78% 34%,#c1ddff 1px,transparent 2px);background-size:260px 210px,320px 200px}
.wp-root.wp-rain:after{content:'';position:absolute;z-index:-1;inset:-25%;opacity:.17;pointer-events:none;background-image:repeating-linear-gradient(106deg,transparent 0px,transparent 26px,#e8f4ff 27px,#e8f4ff 28px,transparent 29px,transparent 55px);background-size:160px 300px;animation:wpRain 3s linear infinite}
@keyframes wpRain{from{background-position:0 -260px}to{background-position:-120px 340px}}
.wp-root.wp-sunny{background:radial-gradient(circle at 75% -10%,rgba(250,191,91,.5),transparent 47%),linear-gradient(160deg,#4f82b6 0%,#215b94 48%,#132a4c 100%)}
.wp-root.wp-cloudy{background:radial-gradient(circle at 40% -10%,rgba(196,216,234,.42),transparent 53%),linear-gradient(160deg,#52647c 0%,#31465e 44%,#152337 100%)}
.wp-root.wp-night{background:radial-gradient(circle at 74% 7%,rgba(97,93,163,.42),transparent 43%),linear-gradient(160deg,#1e294f 0%,#111b39 46%,#080e25 100%)}
.wp-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:22px;flex-wrap:wrap}
.wp-brand{display:flex;align-items:center;gap:10px;font-size:13px;font-weight:800;letter-spacing:.13em;color:#e3ecff;text-decoration:none}
.wp-brand i{display:grid;place-items:center;font-style:normal;width:36px;height:36px;border-radius:13px;background:#ffffff27;font-size:20px}
.wp-nav{display:flex;gap:5px;flex-wrap:wrap}
.wp-nav a,.wp-action{color:#eaf3ff!important;text-decoration:none!important;display:inline-flex;align-items:center;justify-content:center;padding:9px 13px;border-radius:13px;font-weight:650;font-size:12px;background:#ffffff12;border:1px solid #ffffff17;transition:.2s}
.wp-nav a:hover,.wp-action:hover{background:#ffffff30;transform:translateY(-1px)}
.wp-nav a.wp-selected{background:#ffffff31;box-shadow:inset 0 0 0 1px #ffffff3c}
.wp-kicker{font-size:11px;text-transform:uppercase;letter-spacing:.24em;color:#aed3ff;font-weight:800;margin:12px 0 7px}
.wp-h1{font-size:clamp(26px,4.5vw,42px);font-weight:750;letter-spacing:-.045em;line-height:1.17;margin:6px 0 12px}
.wp-muted{color:#c4d3e7;font-size:13px;line-height:1.6}
.wp-soft{color:#9eb4cf}
.wp-big{font-size:clamp(82px,14vw,152px);font-weight:400;line-height:1.03;letter-spacing:-.095em;text-shadow:0 2px 25px #0001}
.wp-big small{font-size:.36em;vertical-align:top;margin:12px 0 0 5px;display:inline-block}
.wp-panel{border:1px solid #ffffff22;border-radius:24px;padding:23px;background:linear-gradient(155deg,#ffffff25,#ffffff09);box-shadow:0 12px 40px #0002;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
.wp-panels{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:15px}
.wp-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:19px}
.wp-list{display:flex;flex-direction:column;gap:12px}
.wp-city{position:relative;overflow:hidden;display:block;text-decoration:none!important;color:#fff!important;min-height:186px;border-radius:24px;border:1px solid #ffffff36;padding:22px 24px;background:linear-gradient(128deg,#739ac4b3,#344b75ce);box-shadow:0 10px 35px #0002;transition:transform .2s}
.wp-city:hover{transform:translateY(-3px)}
.wp-city:nth-child(2){background:linear-gradient(115deg,#526b96,#283962)}
.wp-city:nth-child(3){background:linear-gradient(115deg,#60789b,#314865)}
.wp-city:before{content:'';position:absolute;width:300px;height:300px;right:-65px;top:-140px;background:radial-gradient(circle,#ffffff43,transparent 65%);pointer-events:none}
.wp-cityrow{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.wp-citytitle{font-size:21px;line-height:1.3;font-weight:700;margin:0}
.wp-citytemp{font-size:clamp(46px,7vw,74px);line-height:1;font-weight:350;letter-spacing:-.08em}
.wp-cityfoot{display:flex;justify-content:space-between;gap:12px;margin-top:43px;align-items:end;font-size:12px;color:#e5f0ff}
.wp-chip{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:999px;font-size:11px;font-weight:750;border:1px solid #ffffff3a;background:#ffffff21;color:#ecf7ff}
.wp-chip.wp-good{background:#065f4680;border-color:#6ee7b777;color:#d1fae5}
.wp-chip.wp-warn{background:#9a341270;border-color:#fbbf2488;color:#ffedd5}
.wp-chip.wp-demo{background:#6e548488;border-color:#d9b1ff77;color:#f4ddff}
.wp-meta{font-size:12px;color:#bed3ef;margin-top:10px}
.wp-metric{min-height:155px;display:flex;flex-direction:column;justify-content:space-between}
.wp-metric .wp-kicker{margin:0;letter-spacing:.12em}
.wp-value{font-size:clamp(29px,3.8vw,48px);font-weight:500;letter-spacing:-.07em;line-height:1.18}
.wp-value small{font-size:.35em;letter-spacing:0;font-weight:500;margin-left:5px}
.wp-section{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:27px 0 12px}
.wp-section b{font-size:16px;font-weight:650}
.wp-hour-scroll{display:flex;gap:13px;overflow:auto;padding:7px 0 10px;scrollbar-color:#ffffff50 transparent}
.wp-hour{flex:0 0 86px;display:flex;align-items:center;flex-direction:column;gap:10px;text-align:center;font-size:12px;color:#d5e2f5}
.wp-hour .wp-houricon{font-size:29px}
.wp-hour .wp-hourtemp{font-size:19px;font-weight:650;color:#fff}
.wp-dayrow{display:grid;grid-template-columns:76px 37px 1fr auto auto;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid #ffffff1b;font-size:13px}
.wp-range{height:5px;background:linear-gradient(90deg,#6fb4ff,#b7d9ff,#ffe49b,#f6a44e);border-radius:100px;opacity:.85}
.wp-svg{width:100%;height:auto;min-height:170px;display:block;overflow:visible}
.wp-legend{display:flex;flex-wrap:wrap;gap:11px;font-size:12px;color:#bfd3ef}
.wp-dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px;vertical-align:middle}
.wp-inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.wp-alert{padding:14px 15px;border-radius:15px;margin:10px 0;background:#9f482947;border:1px solid #ffb38655;font-size:13px}
.wp-alert.wp-ok{background:#206f6563;border-color:#63f5bd52}
.wp-empty{border:1px dashed #ffffff42;border-radius:20px;padding:28px 20px;color:#c2d3e9;text-align:center;margin:14px 0}
.wp-table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}.wp-table th,.wp-table td{padding:13px 9px;border-bottom:1px solid #ffffff20}.wp-table th{color:#b5c9e2;font-size:11px;letter-spacing:.06em;font-weight:650}
.wp-foot{font-size:11px;color:#aabed8;line-height:1.7;margin-top:23px}
@media(max-width:950px){.wp-grid3{grid-template-columns:1fr}.wp-nav{width:100%;overflow-x:auto;flex-wrap:nowrap}.wp-nav a{white-space:nowrap}.wp-panels{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:550px){.wp-root{border-radius:0;padding:14px 13px 28px}.wp-top{gap:10px}.wp-brand{font-size:11px}.wp-city{min-height:165px;padding:19px}.wp-cityfoot{margin-top:27px}.wp-panels{gap:9px}.wp-panel{padding:15px;border-radius:19px}.wp-metric{min-height:132px}.wp-value{font-size:32px}.wp-big{font-size:95px}.wp-h1{font-size:29px}.wp-dayrow{grid-template-columns:45px 30px 1fr 32px 32px;gap:5px}.wp-table{font-size:11px}.wp-table th,.wp-table td{padding:10px 3px}}
@media(prefers-reduced-motion:reduce){.wp-root.wp-rain:after{animation:none}.wp-city,.wp-nav a{transition:none}}

