// WEATHER PRO v6: accept ONLY the exact state topic for rooms 301/302/303.
// Output 1: actual normalized readings for Merge; Output 2: raw JSONL; Output 3: Influx writer.
const m=String(msg.topic||'').match(/^building\/floor3\/room(301|302|303)\/state$/);
if(!m || msg.retain===true)return null;
const room=m[1],label={301:'CB40508',302:'CB40509',303:'EEHUB'}[room];
let p=msg.payload;
if(Buffer.isBuffer(p))p=p.toString('utf8');
if(typeof p==='string'){try{p=JSON.parse(p)}catch(e){node.warn('Malformed JSON room '+room);return null}}
if(!p||typeof p!=='object'||Array.isArray(p))return null;
if(p.room!==undefined&&String(p.room)!=='room'+room&&String(p.room)!==room){node.warn('Room payload/topic mismatch: '+room);return null}
function n(v,lo,hi){if(v===null||v===undefined||v==='')return null;const x=Number(v);return Number.isFinite(x)&&x>=lo&&x<=hi?x:null}
function flag(v){if(v===true||v===1||v==='true')return true;if(v===false||v===0||v==='false')return false;return null}
let d={id:'room'+room,room,station:label,t:Date.now(),
 temperature:n(p.temperature,-40,85),humidity:n(p.humidity,0,100),pressure:n(p.pressure,250,1200),
 voltage:n(p.voltage,0,26),current:n(p.current!==undefined?p.current:p.current_ma,-10000,10000),
 power:n(p.power!==undefined?p.power:p.power_mw,-100000,100000),
 mode:(p.sleep_mode==='deep_sleep'||p.mode==='deep_sleep')?'deep_sleep':'normal',
 aht_ok:flag(p.aht_ok),bmp_ok:flag(p.bmp_ok),bme_ok:flag(p.bme_ok),ina_ok:flag(p.ina_ok)};
// aht_ok must reflect *read validity* (no humidity => no valid AHT20 reading).
if(d.humidity===null)d.aht_ok=false;
if(d.pressure===null){d.bmp_ok=d.bmp_ok===true?false:d.bmp_ok;d.bme_ok=d.bme_ok===true?false:d.bme_ok}
if(d.ina_ok===false){d.voltage=null;d.current=null;d.power=null}
if(d.aht_ok===false && d.temperature!==null && d.pressure===null)d.temperature=null;
const out={topic:'__reading',payload:d};
const log={filename:'/share/weatherpro/data/'+new Date(d.t+7*3600000).toISOString().slice(0,10)+'.jsonl',payload:JSON.stringify(d)};
node.status({fill:'green',shape:'dot',text:'ห้อง '+room+' '+new Date().toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok'})});
return [out,log,{payload:d}];

// One source of truth for dashboard. Input __reading/__restore/__tick/__forecast.
const IDS=['room301','room302','room303'],NOW=Date.now(),DAY=86400000,OFFLINE_MS=12*60000;
let st=flow.get('wp6_state')||{rooms:{},hist:{},weather:null,forecastError:null};
for(const id of IDS){
 if(!st.rooms[id])st.rooms[id]={id,name:'ห้อง '+id.slice(-3),source:'none',updatedAt:null,online:false,temperature:null,humidity:null,pressure:null,voltage:null,current:null,power:null,mode:null,aht_ok:null,bmp_ok:null,bme_ok:null,ina_ok:null};
 if(!Array.isArray(st.hist[id]))st.hist[id]=[];
}
function push(o){
 const id=o.id,arr=st.hist[id];if(!IDS.includes(id))return;
 if(arr.some(x=>x.t===o.t))return;
 arr.push({...o,demo:false});arr.sort((a,b)=>a.t-b.t);
 st.hist[id]=arr.filter(x=>x.t>=NOW-DAY&&x.t<=NOW+60000).slice(-1500);
}
function apply(o,restore){
 if(!o||!IDS.includes(o.id)||!Number.isFinite(Number(o.t))||Number(o.t)>NOW+60000||Number(o.t)<NOW-DAY)return;
 o.t=Number(o.t);push(o);let r=st.rooms[o.id];
 if(!r.updatedAt||Number(r.updatedAt)<=o.t){
  for(const k of ['temperature','humidity','pressure','voltage','current','power','mode','aht_ok','bmp_ok','bme_ok','ina_ok'])r[k]=o[k]===undefined?null:o[k];
  r.source='real';r.updatedAt=o.t;r.station=o.station||r.station||null;
 }
}
const topic=String(msg.topic||'');
if(topic==='__reading')apply(msg.payload,false);
else if(topic==='__restore'){
 for(const s of String(msg.payload||'').split(/\r?\n/)){
  if(!s.trim())continue;try{apply(JSON.parse(s),true)}catch(e){}
 }
}
else if(topic==='__forecast'){
 if(msg.payload&&msg.payload.current){st.weather=msg.payload;st.forecastError=null}
 else st.forecastError=String(msg.error||'Forecast error');
}
const errors=[],current={};
function alert(id,type,desc){errors.push(desc);current[id+':'+type]={room:id,type,detail:desc,status:'active',at:NOW}}
for(const id of IDS){
 const r=st.rooms[id];r.online=r.source==='real'&&r.updatedAt!==null&&(NOW-Number(r.updatedAt)<OFFLINE_MS);
 st.hist[id]=st.hist[id].filter(x=>Number(x.t)>=NOW-DAY&&Number(x.t)<=NOW+60000).slice(-1500);
 if(r.source!=='real')continue;
 if(!r.online){alert(id,'offline',r.name+' ไม่ส่งข้อมูลเกิน 12 นาที');continue}
 if(r.humidity===null||r.aht_ok===false)alert(id,'aht_bad',r.name+' AHT20 / ความชื้นอ่านค่าไม่ได้');
 if(r.pressure===null)alert(id,'pressure_bad',r.name+' BMP/BME280 / ความดันอ่านค่าไม่ได้');
 if(r.ina_ok===false)alert(id,'ina_bad',r.name+' INA219 ไม่พร้อม');
 if(r.temperature!==null&&r.temperature>35)alert(id,'hot',r.name+' อุณหภูมิสูง '+Number(r.temperature).toFixed(1)+' °C');
 if(r.humidity!==null&&r.humidity>80)alert(id,'humid',r.name+' ความชื้นสูง '+Number(r.humidity).toFixed(1)+'%');
 // INA219 measures 5V load rail, NOT the battery cell voltage.
 if(r.ina_ok!==false&&r.voltage!==null&&Number(r.voltage)<4.5)alert(id,'rail_low',r.name+' รางจ่ายไฟ 5V ต่ำ '+Number(r.voltage).toFixed(2)+' V');
}
const prior=flow.get('wp6_active_incidents')||{};
const incidents=[];
for(const [key,e] of Object.entries(current))if(!prior[key])incidents.push(e);
for(const [key,e] of Object.entries(prior))if(!current[key])incidents.push({room:e.room,type:e.type,detail:st.rooms[e.room].name+' กลับสู่สถานะปกติ ('+e.type+')',status:'resolved',at:NOW});
flow.set('wp6_active_incidents',current);flow.set('wp6_state',st);
const rooms={};for(const id of IDS)rooms[id]={...st.rooms[id],history:st.hist[id]};
return [{payload:{rooms,weather:st.weather,forecastError:st.forecastError,alerts:errors,updatedAt:NOW}},incidents.length?{payload:incidents}:null];

// Write *only real readings* to InfluxDB v1.x or v2.x; no null -> 0 conversion.
// v2 env: WP_INFLUX_ENABLED=1, WP_INFLUX_VERSION=2,
// WP_INFLUX_URL=http://<host>:8086, WP_INFLUX_ORG, WP_INFLUX_BUCKET, WP_INFLUX_TOKEN
// v1 env: WP_INFLUX_VERSION=1, WP_INFLUX_DB, optional WP_INFLUX_USER/PASS.
if(env.get('WP_INFLUX_ENABLED')!=='1'){node.status({fill:'grey',shape:'ring',text:'Influx disabled until configured'});return null}
const d=msg.payload;if(!d||!/^room30[123]$/.test(d.id))return null;
const url=(env.get('WP_INFLUX_URL')||'').replace(/\/+$/,'');
if(!/^https?:\/\//.test(url)){node.status({fill:'red',shape:'ring',text:'WP_INFLUX_URL missing'});return null}
const fields=[];
function field(name,v){if(v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v)))fields.push(name+'='+Number(v))}
field('temperature',d.temperature);field('humidity',d.humidity);field('pressure',d.pressure);
field('rail_voltage_v',d.voltage);field('current_ma',d.current);field('power_mw',d.power);
const flags=['aht_ok','bmp_ok','bme_ok','ina_ok'];
for(const k of flags)if(d[k]===true||d[k]===false)fields.push(k+'='+(d[k]?'1i':'0i'));
if(!fields.length)return null;
const station=String(d.station||'unknown').replace(/[, =]/g,'_');
const line='weatherpro,room='+d.room+',station='+station+' '+fields.join(',')+' '+d.t;
const headers={'Content-Type':'text/plain; charset=utf-8'};
const version=env.get('WP_INFLUX_VERSION')||'2';let endpoint;
if(version==='2'){
 const org=env.get('WP_INFLUX_ORG'),bucket=env.get('WP_INFLUX_BUCKET'),token=env.get('WP_INFLUX_TOKEN');
 if(!org||!bucket||!token){node.status({fill:'red',shape:'ring',text:'Influx v2 org/bucket/token missing'});return null}
 endpoint=url+'/api/v2/write?org='+encodeURIComponent(org)+'&bucket='+encodeURIComponent(bucket)+'&precision=ms';
 headers.Authorization='Token '+token;
}else if(version==='1'){
 const db=env.get('WP_INFLUX_DB');if(!db){node.status({fill:'red',shape:'ring',text:'Influx v1 database missing'});return null}
 endpoint=url+'/write?db='+encodeURIComponent(db)+'&precision=ms';
 const user=env.get('WP_INFLUX_USER'),pass=env.get('WP_INFLUX_PASS');
 if(user&&pass)headers.Authorization='Basic '+Buffer.from(user+':'+pass).toString('base64');
}else{node.warn('WP_INFLUX_VERSION must be 1 or 2');return null}
node.status({fill:'green',shape:'dot',text:'Influx v'+version+' configured'});
return {method:'POST',url:endpoint,headers,payload:line,room:d.room};

// Sanitized InfluxDB result: NEVER forward msg.url or headers (tokens).
const status=msg.statusCode;
node.status({fill:status===204?'green':'red',shape:status===204?'dot':'ring',text:'Influx HTTP '+status});
if(status!==204)node.warn('Influx write failure HTTP '+status+' (check URL/version/auth/database)');
return {payload:{statusCode:status,room:msg.room,ok:status===204}};

if(!Array.isArray(msg.payload)||!msg.payload.length)return null;
const ts=Date.now(),list=msg.payload;
const ledger={filename:'/share/weatherpro/incidents.jsonl',payload:list.map(e=>JSON.stringify(e)).join('\n')};
if(env.get('WP_TG_ENABLED')!=='1')return [ledger,null];
const token=env.get('WP_TG_BOT_TOKEN'),chat=env.get('WP_TG_CHAT_ID');
if(!token||!chat){node.status({fill:'yellow',shape:'ring',text:'Telegram ENV missing'});return [ledger,null]}
const out=[];for(const e of list){
 const status=e.status==='resolved'?'✅ กลับมาปกติ':'⚠️ แจ้งเตือน';
 const body=status+'\nWeather Pro '+String(e.room).slice(-3)+'\n'+e.detail+'\n'+new Date(e.at||ts).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'});
 out.push({url:'https://api.telegram.org/bot'+token+'/sendMessage',method:'POST',headers:{'Content-Type':'application/json'},payload:{chat_id:chat,text:body}});
}return [ledger,out];

if(msg.statusCode!==200 || !msg.payload || !msg.payload.current || !msg.payload.hourly || !msg.payload.daily){return {topic:'__forecast',payload:null,error:'Open-Meteo HTTP '+String(msg.statusCode||'no response')}}
let p=msg.payload,h=p.hourly,d=p.daily,c=p.current;
let now=new Date(Date.now()+7*3600000).toISOString().slice(0,13);
let start=Math.max(0,h.time.findIndex(x=>x.slice(0,13)>=now));if(start<0)start=0;
let hours=h.time.slice(start,start+24).map((time,i)=>({time,temp:h.temperature_2m[start+i],rain:h.precipitation_probability[start+i],code:h.weather_code[start+i]}));
let days=d.time.slice(0,7).map((date,i)=>({date,hi:d.temperature_2m_max[i],lo:d.temperature_2m_min[i],rain:d.precipitation_probability_max[i],code:d.weather_code[i],uv:d.uv_index_max[i],sunrise:d.sunrise[i],sunset:d.sunset[i]}));
return {topic:'__forecast',payload:{current:c,hours,days,updatedAt:Date.now(),source:'Open-Meteo',locationLabel:'กรุงเทพฯ (ตัวอย่าง)',latitude:13.65,longitude:100.50}};
